import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build watermark map from target_snapshot: device_id -> (reading, applied_event_ts)
    watermark = {}
    for _, row in target_snapshot.iterrows():
        watermark[row["device_id"]] = {
            "reading": row["reading"],
            "applied_event_ts": row["applied_event_ts"],
        }

    # Group cdc_events by device_id
    result = dict(watermark)  # start with carry-forward semantics

    if not cdc_events.empty:
        for device_id, group in cdc_events.groupby("device_id"):
            if device_id in watermark:
                current_ts = watermark[device_id]["applied_event_ts"]
                # filter: event_ts > current_ts (strictly greater survives)
                surviving = group[group["event_ts"] > current_ts]
            else:
                # new device: no watermark, all events qualify
                surviving = group

            if surviving.empty:
                # no surviving events: carry forward existing snapshot (already in result if existed)
                continue

            # pick latest by (event_ts, event_seq) descending
            surviving_sorted = surviving.sort_values(
                by=["event_ts", "event_seq"], ascending=[False, False]
            )
            winner = surviving_sorted.iloc[0]

            result[device_id] = {
                "reading": winner["reading"],
                "applied_event_ts": winner["event_ts"],
            }

    rows = []
    for device_id, data in result.items():
        rows.append(
            {
                "device_id": device_id,
                "reading": data["reading"],
                "applied_event_ts": data["applied_event_ts"],
            }
        )

    new_snapshot = pd.DataFrame(rows, columns=["device_id", "reading", "applied_event_ts"])

    return {"new_snapshot": new_snapshot}
